type Status = "To Do" | "In Progress" | "Waiting for client" | "Waiting for documents" | "Ready for review" | "Under Review" | "Rework required" | "Approved" | "Filed / completed" | "On hold" | "Done";
type Priority = "Urgent" | "High" | "Medium" | "Low";
type AuditEvent = {id:string;at:string;actor:string;action:string;taskTitle?:string;details?:string};
type Task = { id: string; title: string; description: string; status: Status; priority: Priority; category: string; due: string; project: string; client: string; juniors: string[]; financialYear?: string; assessmentYear?: string; taskType?: string; preparer?: string; reviewer?: string; notes?: string; matterName?: string; matterType?: string; applicableAct?: string; documentLinks?: string; uploadedDocuments?: {name:string;dataUrl:string;size:number}[]; statutoryDue?: string; internalDue?: string; checklist?: {text:string;done:boolean}[]; reviewComments?: string; activity?: {at:string;message:string;actor?:string}[]; lastClientFollowUp?: string; nextClientFollowUp?: string; lastFollowUpOutcome?: string; filedDate?: string; filingAck?: string; lastProgressUpdate?: string; completedAt?: string; reworkCount?: number };
const seed: Task[] = [];
const statuses: Status[] = ["To Do","In Progress","Waiting for client","Waiting for documents","Ready for review","Under Review","Rework required","Approved","Filed / completed","On hold"];
const priorities: Priority[] = ["Urgent","High","Medium","Low"];
const initials = (s:string) => s.split(" ").map(x=>x[0]).join("").slice(0,2).toUpperCase();
const localDate = () => { const d = new Date(); return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); };
const isValidISODate = (value:string) => { if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return false; const [y,m,d]=value.split("-").map(Number); const date=new Date(y,m-1,d); return date.getFullYear()===y && date.getMonth()===m-1 && date.getDate()===d; };
const taskDeadlineDates = (t:Task) => [t.statutoryDue,t.internalDue,t.due].filter((v):v is string=>Boolean(v)&&isValidISODate(v as string));

