 const [form,setForm] = useState({title:"",description:"",priority:"Medium" as Priority,due:localDate(),category:"General",project:"",client:"",juniors:"",financialYear:"2025-26",assessmentYear:"2026-27",taskType:"Income tax",preparer:"",reviewer:"Charan Reddy",notes:"",matterName:"",matterType:"",applicableAct:"Determine by matter dates",documentLinks:"",statutoryDue:"",internalDue:localDate(),reviewComments:"",lastClientFollowUp:"",nextClientFollowUp:"",lastFollowUpOutcome:"",filingAck:""});
 useEffect(()=>{try{const saved=localStorage.getItem("officeflow-tasks");if(saved){const parsed=(JSON.parse(saved) as Task[]).map(t=>t.status==="Done"?{...t,status:"Filed / completed" as Status}:t);const demoIds=new Set(["t1","t2","t3","t4"]);const demoTitles=new Set(["Review Q2 GST reconciliation","Prepare client document checklist","Finalize audit observations","Send signed computation"]);setTasks(parsed.filter(t=>!demoIds.has(t.id)&&!demoTitles.has(t.title)).map(t=>({ ...t, client:["Aster Retail","Northstar Foods"].includes(t.client)? "":t.client })));}else{setTasks([]);}setDark(localStorage.getItem("officeflow-dark")==="true");const savedDirectory=localStorage.getItem("officeflow-juniors");if(savedDirectory)setJuniorDirectory(JSON.parse(savedDirectory));const savedClients=localStorage.getItem("officeflow-clients");if(savedClients)setClientDirectory(JSON.parse(savedClients));const savedAudit=localStorage.getItem("officeflow-audit");if(savedAudit)setAuditLog(JSON.parse(savedAudit));setRemindersEnabled(localStorage.getItem("officeflow-reminders")==="true");}catch{}setReady(true)},[]);
