    const {data,error}=await supabase.from("officeflow_workspace_state").select("payload").eq("owner_id",session.user.id).maybeSingle();
    if(error)throw error;
    if(data?.payload){const p=data.payload as any;if(!cancelled){setTasks(Array.isArray(p.tasks)?p.tasks:[]);setClientDirectory(Array.isArray(p.clientDirectory)?p.clientDirectory:[]);setJuniorDirectory(p.juniorDirectory&&typeof p.juniorDirectory==="object"?p.juniorDirectory:{});setAuditLog(Array.isArray(p.auditLog)?p.auditLog:[]);setDark(Boolean(p.dark));setRemindersEnabled(Boolean(p.remindersEnabled));}}
    else {const payload={tasks,juniorDirectory,clientDirectory,auditLog,dark,remindersEnabled};const {error:saveError}=await supabase.from("officeflow_workspace_state").upsert({owner_id:session.user.id,payload,schema_version:1,updated_at:new Date().toISOString()},{onConflict:"owner_id"});if(saveError)throw saveError;}
